import{_ as o,o as a,c as t,a2 as n}from"./chunks/framework.CuUVYbLV.js";const q=JSON.parse('{"title":"05 用图引擎编排团队","description":"教程第 05 章：让角色用 graph_create、graph_add_node、graph_add_edge、graph_run 把三名子代理编成一条流水线，并正确地读回结果。","frontmatter":{"title":"05 用图引擎编排团队","description":"教程第 05 章：让角色用 graph_create、graph_add_node、graph_add_edge、graph_run 把三名子代理编成一条流水线，并正确地读回结果。"},"headers":[],"relativePath":"02-Guide/tutorial/05-graph.md","filePath":"02-Guide/tutorial/05-graph.md"}'),s={name:"02-Guide/tutorial/05-graph.md"};function p(d,e,c,u,l,i){return a(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="_05-用图引擎编排团队-graph" tabindex="-1">05 用图引擎编排团队（Graph） <a class="header-anchor" href="#_05-用图引擎编排团队-graph" aria-label="Permalink to &quot;05 用图引擎编排团队（Graph）&quot;">​</a></h1><p>上一章声明了团队，但派活的过程还是黑盒。这一章把它打开：你会看着角色依次调用 <code>graph_create</code> → <code>graph_add_node</code> ×3 → <code>graph_add_edge</code> ×2 → <code>graph_run</code>，把「实现 → 评审 → 定稿」搭成一张<strong>图（graph，由 <code>graph_create</code> 创建、用 <code>graph_id</code> 寻址的编排容器）</strong>。最后一环最关键：<code>graph_run</code> 是<strong>非阻塞</strong>的，角色调用后必须结束回合，结果要等引擎的下一条提醒。</p><blockquote><p>前置：<a href="/rolebox-docs/02-Guide/tutorial/04-team.html">教程 04 把角色变成团队</a>（三名子代理已注册）｜下一章：<a href="/rolebox-docs/02-Guide/tutorial/06-approval-and-loop.html">06 加上审批门与有界循环</a>｜工具用法：<a href="/rolebox-docs/02-Guide/graph-workflows.html">图工作流</a>、<a href="/rolebox-docs/03-Reference/tools/orchestration-tools.html">编排工具</a></p></blockquote><h2 id="本章造什么" tabindex="-1">本章造什么 <a class="header-anchor" href="#本章造什么" aria-label="Permalink to &quot;本章造什么&quot;">​</a></h2><p>一条三节点的流水线：<code>implement</code>（<code>code-reviewer--coder</code>）→ <code>review</code>（<code>code-reviewer--reviewer</code>）→ <code>document</code>（<code>code-reviewer--doc-writer</code>）。每个节点是一次<strong>派发（dispatch，把一段提示词交给某个代理执行）</strong>，上游的产出会作为上下文交给下游。</p><h2 id="第-1-步-在会话里提出要求" tabindex="-1">第 1 步：在会话里提出要求 <a class="header-anchor" href="#第-1-步-在会话里提出要求" aria-label="Permalink to &quot;第 1 步：在会话里提出要求&quot;">​</a></h2><p>回到 <code>code-reviewer</code> 会话，说一句话就行——你不需要自己调工具，父角色的系统提示词里已经写明怎么用这组工具派活：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>在 ~/rolebox-lab 下写一个 scripts/hello.sh，打印一行问候。</span></span>
<span class="line"><span>跑成一条流水线：coder 先实现，reviewer 接着审，</span></span>
<span class="line"><span>doc-writer 最后写一段面向使用者的说明。</span></span>
<span class="line"><span>每一步都保留产出，全部跑完再给我汇总。</span></span></code></pre></div><h2 id="第-2-步-角色建图" tabindex="-1">第 2 步：角色建图 <a class="header-anchor" href="#第-2-步-角色建图" aria-label="Permalink to &quot;第 2 步：角色建图&quot;">​</a></h2><p>父角色先开一张图。<code>graph_create</code> 只需要人类可读的 <code>name</code>（它同时就是 <code>graph_id</code>）与可选的图级 <code>budget</code>，再用 <code>graph_add_node</code> 加三个节点，<code>agent</code> 填第 04 章注册的子代理 id：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>graph_create   { &quot;name&quot;: &quot;hello-pipeline&quot;, &quot;budget&quot;: { &quot;max_total_cost_usd&quot;: 5 } }</span></span>
<span class="line"><span>               → { &quot;graph_id&quot;: &quot;hello-pipeline&quot;, &quot;name&quot;: &quot;hello-pipeline&quot;,</span></span>
<span class="line"><span>                   &quot;created_at&quot;: &quot;2026-09-17T06:10:41.512Z&quot; }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>graph_add_node { &quot;graph_id&quot;: &quot;hello-pipeline&quot;, &quot;id&quot;: &quot;implement&quot;,</span></span>
<span class="line"><span>                 &quot;agent&quot;: &quot;code-reviewer--coder&quot;, &quot;prompt&quot;: &quot;写 scripts/hello.sh……&quot; }</span></span>
<span class="line"><span>               → { &quot;node_id&quot;: &quot;implement&quot;, &quot;graph_id&quot;: &quot;hello-pipeline&quot;, &quot;created&quot;: true }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>graph_add_node { &quot;graph_id&quot;: &quot;hello-pipeline&quot;, &quot;id&quot;: &quot;review&quot;,</span></span>
<span class="line"><span>                 &quot;agent&quot;: &quot;code-reviewer--reviewer&quot;, &quot;prompt&quot;: &quot;审查上游实现……&quot; }</span></span>
<span class="line"><span>               → { &quot;node_id&quot;: &quot;review&quot;, &quot;graph_id&quot;: &quot;hello-pipeline&quot;, &quot;created&quot;: true }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>graph_add_node { &quot;graph_id&quot;: &quot;hello-pipeline&quot;, &quot;id&quot;: &quot;document&quot;,</span></span>
<span class="line"><span>                 &quot;agent&quot;: &quot;code-reviewer--doc-writer&quot;, &quot;prompt&quot;: &quot;写两行使用说明……&quot; }</span></span>
<span class="line"><span>               → { &quot;node_id&quot;: &quot;document&quot;, &quot;graph_id&quot;: &quot;hello-pipeline&quot;, &quot;created&quot;: true }</span></span></code></pre></div><p>节点本身不定义顺序。顺序由边决定：<code>graph_add_edge</code> 给 <code>from</code> / <code>to</code>，<code>type</code> 省略即 <code>always</code>（上游一有结果就激活下游）：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>graph_add_edge { &quot;graph_id&quot;: &quot;hello-pipeline&quot;, &quot;from&quot;: &quot;implement&quot;, &quot;to&quot;: &quot;review&quot; }</span></span>
<span class="line"><span>               → { &quot;edge_id&quot;: &quot;implement-&gt;review&quot;, &quot;from&quot;: &quot;implement&quot;, &quot;to&quot;: &quot;review&quot;, &quot;type&quot;: &quot;always&quot; }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>graph_add_edge { &quot;graph_id&quot;: &quot;hello-pipeline&quot;, &quot;from&quot;: &quot;review&quot;, &quot;to&quot;: &quot;document&quot; }</span></span>
<span class="line"><span>               → { &quot;edge_id&quot;: &quot;review-&gt;document&quot;, &quot;from&quot;: &quot;review&quot;, &quot;to&quot;: &quot;document&quot;, &quot;type&quot;: &quot;always&quot; }</span></span></code></pre></div><p>到这里还没有任何子代理开始干活：建图只是往图的注册表里写结构，加节点与加边失败会整条拒绝（图保持不变）。想先确认结构能不能跑，可以让角色用 <code>graph_run</code> 的 <code>dry_run: true</code> 做一次执行级校验——它返回 <code>validation</code>，不派发任何节点。</p><h2 id="第-3-步-graph-run-是非阻塞的" tabindex="-1">第 3 步：graph_run 是非阻塞的 <a class="header-anchor" href="#第-3-步-graph-run-是非阻塞的" aria-label="Permalink to &quot;第 3 步：graph_run 是非阻塞的&quot;">​</a></h2><p>真正的执行只有一句 <code>graph_run</code>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>graph_run { &quot;graph_id&quot;: &quot;hello-pipeline&quot; }</span></span>
<span class="line"><span>          → { &quot;graph_id&quot;: &quot;hello-pipeline&quot;, &quot;phase&quot;: &quot;executing&quot;,</span></span>
<span class="line"><span>              &quot;active_nodes&quot;: [&quot;implement&quot;], &quot;pending_nodes&quot;: [&quot;review&quot;, &quot;document&quot;] }</span></span></code></pre></div><p>返回值立刻就到：<code>phase</code> 是 <code>executing</code>，<code>active_nodes</code> 是刚被派发的根节点 <code>implement</code>，<code>pending_nodes</code> 是还没轮到的两个。<strong>它不等它们跑完</strong>——派发完所有就绪的根节点就返回。</p><p>所以工具契约要求角色在 <code>graph_run</code> 之后<strong>结束当前回合</strong>，把后续交给引擎：</p><ol><li>引擎在后台推进图；</li><li>全部节点结束时，它往这个会话注入一条 <code>[GRAPH COMPLETE]</code> 系统提醒（有节点在等人工审批时是 <code>[GRAPH BLOCKED]</code>，见第 06 章）；</li><li>提醒到达后，角色在<strong>下一回合</strong>读结果。</li></ol><p>如果角色在 <code>graph_run</code> 之后不结束回合，而是改用 <code>graph_status</code> 反复轮询，它就把非阻塞引擎当成阻塞调用了——这是本章最值得记住的一条。</p><h2 id="第-4-步-等-graph-complete-只读一次结果" tabindex="-1">第 4 步：等 [GRAPH COMPLETE]，只读一次结果 <a class="header-anchor" href="#第-4-步-等-graph-complete-只读一次结果" aria-label="Permalink to &quot;第 4 步：等 [GRAPH COMPLETE]，只读一次结果&quot;">​</a></h2><p>流水线跑完后，会话里会多出一条系统提醒，形状是固定的：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;system-reminder&gt;</span></span>
<span class="line"><span>[GRAPH COMPLETE]</span></span>
<span class="line"><span>graph: hello-pipeline</span></span>
<span class="line"><span>phase: complete</span></span>
<span class="line"><span>nodes: completed=3</span></span>
<span class="line"><span></span></span>
<span class="line"><span>→ Read all results: graph_status(graph_id=&quot;hello-pipeline&quot;, include_output=true)</span></span>
<span class="line"><span>&lt;/system-reminder&gt;</span></span></code></pre></div><p>下一回合，角色按提醒的指示回读一次。默认的 <code>graph_status</code> 给一张状态表；要连产出一起取回来，用 <code>format: &quot;json&quot;</code> 配 <code>include_output: true</code>（也可以只给 <code>node_id</code> 看单个节点）：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>graph_status { &quot;graph_id&quot;: &quot;hello-pipeline&quot; }</span></span>
<span class="line"><span>             → Graph &quot;hello-pipeline&quot;  [phase: complete]</span></span>
<span class="line"><span>                 NODE                  STATUS      AGENT</span></span>
<span class="line"><span>                 implement             completed   code-reviewer--coder</span></span>
<span class="line"><span>                 review                completed   code-reviewer--reviewer</span></span>
<span class="line"><span>                 document              completed   code-reviewer--doc-writer</span></span>
<span class="line"><span></span></span>
<span class="line"><span>graph_status { &quot;graph_id&quot;: &quot;hello-pipeline&quot;, &quot;format&quot;: &quot;json&quot;, &quot;include_output&quot;: true }</span></span>
<span class="line"><span>             → { &quot;graph_id&quot;: &quot;hello-pipeline&quot;, &quot;phase&quot;: &quot;complete&quot;,</span></span>
<span class="line"><span>                 &quot;nodes&quot;: [ { &quot;node_id&quot;: &quot;implement&quot;, &quot;status&quot;: &quot;completed&quot;,</span></span>
<span class="line"><span>                              &quot;agent&quot;: &quot;code-reviewer--coder&quot;,</span></span>
<span class="line"><span>                              &quot;output&quot;: &quot;已创建 scripts/hello.sh……&quot; }, … ] }</span></span></code></pre></div><p><strong>只在提醒没到时才轮询</strong>：如果很久既没有 <code>[GRAPH COMPLETE]</code> 也没有 <code>[GRAPH BLOCKED]</code>，用一次 <code>graph_status</code> 看看是不是有节点卡在 <code>running</code>，再决定继续等、重试还是取消；不要在同一个回合里反复查。</p><h2 id="第-5-步-观测与人工叫停" tabindex="-1">第 5 步：观测与人工叫停 <a class="header-anchor" href="#第-5-步-观测与人工叫停" aria-label="Permalink to &quot;第 5 步：观测与人工叫停&quot;">​</a></h2><p><code>graph_status</code> 不只在结束时有用：图在跑的时候也可以查（<code>phase</code> 是 <code>executing</code>、哪个节点 <code>running</code>），它是只读的，不会打断推进。<code>graph_cancel</code> 则是给<strong>人</strong>的控制面——在会话里直接说「取消那张图」，或让角色调用：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>graph_cancel { &quot;graph_id&quot;: &quot;hello-pipeline&quot;, &quot;node_id&quot;: &quot;document&quot;, &quot;cascade&quot;: true }</span></span>
<span class="line"><span>             → { &quot;cancelled&quot;: [&quot;document&quot;], &quot;graph_id&quot;: &quot;hello-pipeline&quot; }</span></span></code></pre></div><p>返回的 <code>cancelled</code> 是引擎实际取消的节点 id；<code>cascade: true</code> 会把该节点传递下游的节点一并取消。工具契约把 <code>graph_cancel</code> 定义为人工监控与干预手段，不要用它让角色自我取消正在跑的工作流。</p><h2 id="常见错误" tabindex="-1">常见错误 <a class="header-anchor" href="#常见错误" aria-label="Permalink to &quot;常见错误&quot;">​</a></h2><ul><li><strong><code>graph_run</code> 之后继续等</strong>：调用已经返回，结果要靠提醒；在同一个回合里等是等不到的。</li><li><strong>反复轮询 <code>graph_status</code></strong>：提醒会到，轮询只在提醒缺席时兜底。</li><li><strong>回读时忘了 <code>include_output</code></strong>：默认渲染的是状态表，产出要显式索取。</li><li><strong><code>agent</code> 写成显示名</strong>：这里要的是子代理 id（<code>code-reviewer--coder</code>），不是 <code>Coder</code>。</li><li><strong>节点 <code>id</code> 重复</strong>：同一张图内必须唯一，重复的 <code>graph_add_node</code> 会被直接拒绝。</li><li><strong>边连到不存在的节点</strong>：<code>from</code> / <code>to</code> 必须已经用 <code>graph_add_node</code> 声明过，否则这条边会被结构校验拒绝。</li><li><strong>加回边却不声明循环组</strong>：本章只搭直线链路；一条纯 <code>always</code> 的环永远无法激活，<code>graph_run</code> 前的执行级校验会直接报错——回环要用 <code>graph_add_loop</code>（第 06 章）。</li></ul><h2 id="你现在拥有什么" tabindex="-1">你现在拥有什么 <a class="header-anchor" href="#你现在拥有什么" aria-label="Permalink to &quot;你现在拥有什么&quot;">​</a></h2><ul><li>一张跑通的图：<code>implement → review → document</code>，三个节点分别由三名子代理承接；</li><li>「非阻塞 → 结束回合 → <code>[GRAPH COMPLETE]</code> → 回读一次」这条固定节奏；</li><li>两个随时可用的入口：<code>graph_status</code>（观测）与 <code>graph_cancel</code>（人工叫停）。</li></ul><p>下一章 <a href="/rolebox-docs/02-Guide/tutorial/06-approval-and-loop.html">06 加上审批门与有界循环</a>：在定稿前插入人工审批门，并给评审返工加上硬性遍历上限。</p><h2 id="备注" tabindex="-1">备注 <a class="header-anchor" href="#备注" aria-label="Permalink to &quot;备注&quot;">​</a></h2><ul><li>图生存在内存注册表里；要跨会话查看，用 <code>graph_status</code> 的 <code>scope</code> 参数（<code>persisted</code> 读磁盘上的引擎状态）。</li><li>三条边类型（<code>always</code> / <code>on_signal</code> / <code>on_condition</code>）、多上游的 <code>join</code> 汇聚与数据透传字段，见<a href="/rolebox-docs/02-Guide/graph-workflows.html">图工作流</a>；节点状态机与信号传播的内部语义见<a href="/rolebox-docs/04-Advanced/graph-engine.html">图执行引擎</a>。</li></ul>`,38)])])}const h=o(s,[["render",p]]);export{q as __pageData,h as default};
